/**
 * api.js — all data fetching
 *
 * TheAudioDB  → via local proxy at /api/audiodb/... (avoids CORS entirely)
 * iTunes      → fetched directly (has native CORS support from browsers)
 */

// ── TheAudioDB via local proxy ────────────────────────────────────────────────
async function adbFetch(endpoint, params = {}) {
  const qs = new URLSearchParams(params).toString();
  const url = `/api/audiodb/${endpoint}${qs ? '?' + qs : ''}`;
  const res = await fetch(url);
  if (!res.ok) throw new Error(`AudioDB proxy ${res.status}`);
  return res.json();
}

export const adbSearchArtist = (s) => adbFetch('search.php', { s });
export const adbSearchAlbums = (s) => adbFetch('searchalbum.php', { s });
export const adbSearchTracks = (s) => adbFetch('searchtrack.php', { s });

// ── iTunes Search API (native CORS, no proxy needed) ─────────────────────────
export async function itunesSearchSongs(artist, limit = 100) {
  const url = `https://itunes.apple.com/search?${new URLSearchParams({
    term: artist, entity: 'song', limit,
  })}`;
  const res = await fetch(url, { signal: AbortSignal.timeout(8000) });
  if (!res.ok) throw new Error(`iTunes ${res.status}`);
  return res.json();
}

// ── Preview matching ──────────────────────────────────────────────────────────
export function buildPreviewMap(results = []) {
  const map = {};
  for (const r of results) {
    if (!r.previewUrl) continue;
    // Primary key: normalised artist + track
    const pk = norm(r.artistName) + '||' + norm(r.trackName);
    if (!map[pk]) map[pk] = r.previewUrl;
    // Fallback key: track name only
    const tk = '_t_' + norm(r.trackName);
    if (!map[tk]) map[tk] = r.previewUrl;
  }
  return map;
}

export function lookupPreview(map, artist, track) {
  return (
    map[norm(artist) + '||' + norm(track)] ||
    map['_t_' + norm(track)] ||
    null
  );
}

function norm(s = '') {
  return s.toLowerCase().replace(/[^a-z0-9]/g, '');
}
